:root {
  --night: #17100a;
  --ink: #2b1a0e;
  --leather: #5a3320;
  --rust: #b5461f;
  --gold: #e0a32e;
  --ember: #f2a03d;
  --sand: #e6d3ae;
  --parchment: #f4e8ce;
  --cactus: #6b8558;
  --muted: #8a7458;

  --display: "Rye", "Bitter", Georgia, serif;
  --slab: "Smokum", "Rye", Georgia, serif;
  --type: "Special Elite", "Courier New", monospace;
  --body: "Bitter", Georgia, "Times New Roman", serif;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  color: var(--ink);
  background: var(--parchment);
  font-family: var(--body);
  font-size: 16px;
  line-height: 1.6;
  overflow-x: hidden;
}

::selection {
  color: var(--parchment);
  background: var(--rust);
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  display: block;
  max-width: 100%;
}

button {
  font: inherit;
}

.skip-link {
  position: fixed;
  z-index: 100;
  top: 1rem;
  left: 1rem;
  padding: 0.7rem 1rem;
  color: var(--parchment);
  background: var(--rust);
  font-family: var(--type);
  transform: translateY(-250%);
}

.skip-link:focus {
  transform: translateY(0);
}

/* Aged paper grain over the whole page */
.grain {
  position: fixed;
  z-index: 30;
  inset: 0;
  pointer-events: none;
  opacity: 0.09;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

/* ---------- Header ---------- */

.site-header {
  position: absolute;
  z-index: 10;
  top: 0;
  left: 0;
  display: grid;
  width: 100%;
  grid-template-columns: 1fr auto 1fr;
  gap: 1.5rem;
  align-items: center;
  padding: 1.1rem 3.5vw;
  color: var(--parchment);
  border-bottom: 1px solid rgba(240, 220, 180, 0.22);
}

.brand {
  display: inline-flex;
  gap: 0.75rem;
  align-items: center;
  width: max-content;
}

.brand-hat {
  color: var(--gold);
  filter: drop-shadow(0 2px 0 rgba(0, 0, 0, 0.35));
}

.brand-text {
  display: grid;
  line-height: 1.1;
}

.brand-text strong {
  font-family: var(--display);
  font-size: 1.05rem;
  font-weight: 400;
  letter-spacing: 0.06em;
}

.brand-text em {
  color: var(--gold);
  font-family: var(--type);
  font-size: 0.6rem;
  font-style: normal;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

nav {
  display: flex;
  gap: 2.2rem;
  font-family: var(--type);
  font-size: 0.76rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

nav a {
  padding-bottom: 0.2rem;
  border-bottom: 1px solid transparent;
  transition: color 160ms ease, border-color 160ms ease;
}

nav a:hover {
  color: var(--gold);
  border-bottom-color: var(--gold);
}

.site-header > .button {
  justify-self: end;
}

/* ---------- Buttons ---------- */

.button {
  display: inline-flex;
  gap: 1.1rem;
  align-items: center;
  justify-content: space-between;
  padding: 0.85rem 1.4rem;
  border: 2px solid currentColor;
  border-radius: 2px;
  font-family: var(--type);
  font-size: 0.78rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: transform 180ms ease, color 180ms ease, background 180ms ease,
    box-shadow 180ms ease;
}

.button:hover {
  transform: translateY(-3px);
}

.button-ghost {
  border-color: rgba(240, 220, 180, 0.5);
}

.button-ghost:hover {
  color: var(--ink);
  background: var(--sand);
  border-color: var(--sand);
}

.button-primary {
  color: var(--ink);
  background: var(--gold);
  border-color: var(--ink);
  box-shadow: 4px 4px 0 var(--ink);
}

.button-primary:hover {
  background: var(--ember);
  box-shadow: 7px 7px 0 var(--ink);
}

.button-dark {
  color: var(--parchment);
  background: var(--ink);
  border-color: var(--ink);
  box-shadow: 4px 4px 0 rgba(43, 26, 14, 0.28);
}

.button-dark:hover {
  background: var(--leather);
  box-shadow: 7px 7px 0 rgba(43, 26, 14, 0.28);
}

.text-link {
  padding-bottom: 0.3rem;
  border-bottom: 1px solid currentColor;
  font-family: var(--type);
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transition: color 160ms ease;
}

.text-link:hover {
  color: var(--gold);
}

/* ---------- Hero ---------- */

.hero {
  position: relative;
  display: grid;
  min-height: 100vh;
  padding: 10rem 6vw 7rem;
  grid-template-columns: minmax(0, 1.05fr) minmax(360px, 0.95fr);
  gap: 5vw;
  align-items: center;
  color: var(--parchment);
  background: var(--night);
  overflow: hidden;
}

.hero-scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(105deg, rgba(15, 9, 5, 0.9) 8%, rgba(15, 9, 5, 0.55) 46%, rgba(15, 9, 5, 0.25) 72%),
    linear-gradient(to top, rgba(15, 9, 5, 0.85), transparent 45%);
}

.hero-copy,
.telegram {
  position: relative;
  z-index: 2;
}

.eyebrow {
  display: inline-flex;
  gap: 0.7rem;
  align-items: center;
  margin: 0 0 1.8rem;
  padding: 0.45rem 0.95rem;
  color: var(--gold);
  border: 1px solid rgba(224, 163, 46, 0.55);
  border-radius: 2px;
  background: rgba(20, 12, 6, 0.5);
  font-family: var(--type);
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.eyebrow img {
  color: var(--gold);
}

h1 {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(3.2rem, 8vw, 7.2rem);
  font-weight: 400;
  line-height: 0.98;
  text-shadow: 5px 5px 0 rgba(0, 0, 0, 0.45);
}

h1 span {
  display: block;
}

h1 .line-2 {
  padding-left: 0.12em;
  color: var(--gold);
}

h1 .line-3 {
  padding-left: 0.24em;
  color: var(--ember);
}

.hero-intro {
  max-width: 34rem;
  margin: 2.2rem 0 2.4rem;
  color: #ded0b6;
  font-size: clamp(1rem, 1.4vw, 1.2rem);
  line-height: 1.75;
}

.hero-actions {
  display: flex;
  gap: 2rem;
  align-items: center;
  flex-wrap: wrap;
}

.hero-index {
  position: absolute;
  right: 1.6rem;
  bottom: 2.5rem;
  color: rgba(224, 163, 46, 0.65);
  font-family: var(--type);
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  writing-mode: vertical-rl;
}

/* ---------- Telegram card ---------- */

.telegram {
  background: var(--parchment);
  border: 2px solid var(--ink);
  border-radius: 3px;
  box-shadow: 14px 14px 0 rgba(0, 0, 0, 0.35);
  transform: rotate(-1.4deg);
}

.telegram-head {
  display: flex;
  justify-content: space-between;
  padding: 0.7rem 1.1rem;
  color: var(--parchment);
  background: var(--ink);
  font-family: var(--type);
  font-size: 0.66rem;
  letter-spacing: 0.14em;
}

.telegram-body {
  min-height: 400px;
  padding: 1.8rem;
  color: var(--leather);
  font-family: var(--type);
  font-size: clamp(0.74rem, 1vw, 0.92rem);
  line-height: 1.9;
}

.telegram-body p {
  margin: 0;
}

.telegram-meta {
  margin-bottom: 1rem !important;
  padding-bottom: 0.6rem;
  color: var(--rust);
  border-bottom: 1px dashed rgba(90, 51, 32, 0.4);
  font-size: 0.7rem;
  letter-spacing: 0.08em;
}

.telegram-body .telegram-meta:last-child {
  margin: 1rem 0 0 !important;
  padding: 0.6rem 0 0;
  border-top: 1px dashed rgba(90, 51, 32, 0.4);
  border-bottom: 0;
}

.telegram-body .prompt {
  color: var(--rust);
  font-weight: 700;
}

.tree {
  margin: 0.9rem 0;
}

.tree b {
  color: var(--ink);
}

.tree i {
  color: var(--muted);
  font-size: 0.8em;
}

.cursor {
  color: var(--rust);
  animation: blink 1.05s step-end infinite;
}

@keyframes blink {
  50% { opacity: 0; }
}

/* ---------- Rope divider ---------- */

.rope-divider {
  height: 14px;
  background: url("assets/rope.svg") repeat-x center / auto 14px;
  border-top: 2px solid var(--ink);
  border-bottom: 2px solid var(--ink);
  background-color: var(--sand);
}

/* ---------- Shared section furniture ---------- */

.section {
  padding: 7rem 6vw;
}

.section-label {
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  margin-bottom: 3.5rem;
  font-family: var(--type);
  font-size: 0.74rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.section-label span {
  color: var(--rust);
}

.section-label p {
  margin: 0;
}

.section-label.light {
  color: var(--sand);
}

.section-label.light span {
  color: var(--gold);
}

.overline {
  display: block;
  margin-bottom: 1.3rem;
  color: var(--rust);
  font-family: var(--type);
  font-size: 0.74rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

h2 {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(2.6rem, 5.4vw, 5rem);
  font-weight: 400;
  line-height: 1.05;
}

h2 em {
  display: inline-block;
  color: var(--rust);
  font-family: var(--slab);
