  font-family: var(--type);
  font-size: 0.66rem;
  letter-spacing: 0.14em;
}

.poster-title {
  margin: 0.5rem 0 0;
  color: var(--ink);
  font-family: var(--slab);
  font-size: clamp(3.6rem, 7vw, 5.4rem);
  line-height: 0.9;
}

.poster-sub {
  margin: 0 0 1.2rem;
  font-family: var(--type);
  font-size: 0.82rem;
  letter-spacing: 0.06em;
}

.poster-portrait {
  margin: 0 auto 1.2rem;
  padding: 1rem;
