}

.poster-name {
  margin: 0 0 1.3rem;
  color: var(--ink);
  font-family: var(--display);
  font-size: 1.25rem;
}

.poster-facts {
  margin: 0 0 1.5rem;
  padding-top: 1rem;
  border-top: 1px solid rgba(90, 51, 32, 0.35);
