  color: var(--sand);
  background:
    linear-gradient(rgba(23, 16, 10, 0.94), rgba(23, 16, 10, 0.94)),
    repeating-linear-gradient(
      92deg,
      #2f1d10 0 7px,
      #3a2414 7px 9px,
      #241608 9px 22px
    );
  overflow: hidden;
}

.workflow-cactus {
  position: absolute;
  right: 3vw;
  bottom: 3rem;
  color: rgba(107, 133, 88, 0.28);
  pointer-events: none;
}

.workflow-header h2 em {
  color: var(--gold);
}

.workflow-header > p {
  color: #bda98a;
}

.workflow-list {
  position: relative;
  z-index: 2;
  border-top: 1px solid rgba(224, 163, 46, 0.28);
}

.workflow-list a {
  display: grid;
  padding: 1.5rem 0.6rem;
  grid-template-columns: 0.35fr 1.3fr 2fr 0.85fr auto;
  gap: 1.2rem;
  align-items: center;
  border-bottom: 1px solid rgba(224, 163, 46, 0.28);
  transition: padding 200ms ease, color 200ms ease, background 200ms ease;
}

.workflow-list a:hover {
  padding-right: 1.2rem;
  padding-left: 1.2rem;
  color: var(--ink);
  background: var(--gold);
}

.workflow-id {
  color: var(--gold);
  font-family: var(--type);
  font-size: 0.74rem;
}

.workflow-list strong {
  font-family: var(--display);
  font-size: 1.15rem;
  font-weight: 400;
}

.workflow-desc {
  color: #bda98a;
  font-size: 0.95rem;
}

.workflow-list b {
  font-size: 1.1rem;
}

.workflow-list a:hover .workflow-id,
.workflow-list a:hover .workflow-desc {
  color: var(--ink);
}

.workflow-list a:hover code {
  color: var(--gold);
  background: var(--ink);
}

/* ---------- Start ---------- */

.start {
  background:
    radial-gradient(circle at 80% 15%, rgba(224, 163, 46, 0.22), transparent 55%),
    var(--parchment);
  border-bottom: 2px solid var(--ink);
}

.start-grid {
  display: grid;
  grid-template-columns: 1fr 1.15fr;
  gap: 6vw;
  align-items: center;
}

.start-copy {
  position: relative;
}

.start-copy h2 em {
  color: var(--rust);
}

.start-copy > p {
  margin: 1.8rem 0 2.2rem;
}

.start-boot {
  position: absolute;
  right: 1rem;
  bottom: -2rem;
  color: rgba(90, 51, 32, 0.22);
  pointer-events: none;
  transform: rotate(-12deg);
}

.code-panel {
  color: var(--sand);
  background: var(--ink);
  border: 2px solid var(--ink);
  border-radius: 3px;
  box-shadow: 12px 12px 0 rgba(43, 26, 14, 0.25);
}

.code-tabs {
  display: flex;
  border-bottom: 1px solid rgba(224, 163, 46, 0.35);
}

.code-tabs button {
  padding: 1rem 1.4rem;
  border: 0;
  color: #a08f74;
  background: transparent;
  cursor: pointer;
  font-family: var(--type);
  font-size: 0.76rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: color 160ms ease, box-shadow 160ms ease;
}

.code-tabs button.active {
  color: var(--gold);
  box-shadow: inset 0 -3px var(--gold);
}

.code-tabs button:hover {
  color: var(--ember);
}

.code-tabs .copy-button {
  margin-left: auto;
  color: var(--sand);
}

.code-panel pre {
  min-height: 235px;
  margin: 0;
  padding: 2.2rem;
  overflow: auto;
  font-family: var(--type);
  font-size: clamp(0.76rem, 1.05vw, 0.94rem);
  line-height: 2.1;
}

.code-panel .comment {
  color: #97835f;
}

/* ---------- CTA ---------- */

.cta {
  position: relative;
  padding: 9rem 6vw 7rem;
  color: var(--parchment);
  background: var(--night);
  overflow: hidden;
  text-align: center;
}

.cta::after {
  position: absolute;
  left: 50%;
  bottom: -18rem;
  width: 36rem;
  height: 36rem;
  margin-left: -18rem;
  content: "";
  border-radius: 50%;
  background: radial-gradient(circle, rgba(224, 163, 46, 0.35), transparent 68%);
}

.cta-track {
  position: absolute;
  top: 2.2rem;
  left: 0;
  display: flex;
  width: max-content;
  color: rgba(224, 163, 46, 0.22);
  font-family: var(--display);
  font-size: 1.5rem;
  white-space: nowrap;
  animation: marquee 28s linear infinite;
}

@keyframes marquee {
  to { transform: translateX(-50%); }
}

.cta-inner {
  position: relative;
  z-index: 2;
  display: grid;
  justify-items: center;
}

.cta-inner img {
  color: var(--gold);
  margin-bottom: 1.5rem;
}

.cta-inner > p {
  margin: 0 0 1.6rem;
  color: var(--gold);
  font-family: var(--type);
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.cta h2 {
  margin-bottom: 3rem;
  text-shadow: 4px 4px 0 rgba(0, 0, 0, 0.4);
}

.cta h2 em {
  color: var(--gold);
}

/* ---------- Footer ---------- */

footer {
  display: grid;
  padding: 2rem 3.5vw;
  grid-template-columns: 1fr auto 1fr;
  gap: 1.5rem;
  align-items: center;
  color: #a08f74;
  background: var(--ink);
  border-top: 2px solid var(--gold);
  font-family: var(--type);
  font-size: 0.72rem;
  letter-spacing: 0.06em;
}

footer .brand-text strong {
  color: var(--sand);
}

footer p {
  margin: 0;
}

footer p:last-child {
  justify-self: end;
}

/* ---------- Reveal animation ---------- */

.reveal {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 700ms ease, transform 700ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

.poster.reveal {
  transform: translateY(26px) rotate(-2deg);
}

.poster.reveal.visible {
  transform: translateY(0) rotate(-2deg);
}

.telegram.reveal {
  transform: translateY(26px) rotate(-1.4deg);
}

.telegram.reveal.visible {
  transform: translateY(0) rotate(-1.4deg);
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .reveal,
  .poster.reveal,
  .telegram.reveal { opacity: 1; transform: none; transition: none; }
  .poster.reveal.visible { transform: rotate(-2deg); }
  .telegram.reveal.visible { transform: rotate(-1.4deg); }
  .cta-track, .cursor { animation: none; }
  .button, .supply-card, .poster { transition: none; }
}

/* ---------- Responsive ---------- */

@media (max-width: 1000px) {
  .site-header {
    grid-template-columns: 1fr auto;
  }

  .site-header nav {
    display: none;
  }

  .hero {
    min-height: auto;
    padding-top: 8.5rem;
    grid-template-columns: 1fr;
    gap: 3.5rem;
  }

  .hero-shade {
    background: linear-gradient(to top, rgba(15, 9, 5, 0.94) 30%, rgba(15, 9, 5, 0.6));
  }

  .telegram {
    max-width: 620px;
  }

  .hero-index {
    display: none;
  }

  .poster-grid,
  .start-grid {
    grid-template-columns: 1fr;
    gap: 3.5rem;
  }

  .poster {
    max-width: 420px;
  }

  .supply-grid {
    grid-template-columns: 1fr;
  }

  .supply-card {
    min-height: 0;
  }

  .supply-card img {
    margin-top: 2rem;
  }

  .supply-card p {
    min-height: 0;
  }

  .section-heading,
  .workflow-header {
    gap: 1.8rem;
    align-items: flex-start;
    flex-direction: column;
  }

  .workflow-list a {
    grid-template-columns: 0.4fr 1fr auto;
  }

  .workflow-desc,
  .workflow-list code {
    display: none;
  }

  .workflow-cactus {
    width: 120px;
    height: 120px;
    opacity: 0.5;
  }

  .start-boot {
    display: none;
  }
}

@media (max-width: 620px) {
  .site-header {
    padding: 0.9rem 1.1rem;
  }

  .site-header > .button {
    display: none;
  }

  .hero,
  .section,
  .cta {
    padding-right: 1.2rem;
    padding-left: 1.2rem;
  }

  .hero {
    padding-top: 7.5rem;
    padding-bottom: 4rem;
  }

  .section {
    padding-top: 4.5rem;
    padding-bottom: 4.5rem;
  }

  .cta {
    padding-top: 6.5rem;
  }

  h1 {
    font-size: clamp(2.6rem, 13vw, 4rem);
  }

  h2 {
    font-size: clamp(2rem, 9.5vw, 3rem);
  }

  .hero-actions {
    align-items: flex-start;
    flex-direction: column;
    gap: 1.4rem;
  }

  .telegram-body {
    min-height: 0;
    padding: 1.2rem;
  }

  .poster {
    padding: 1.6rem 1.1rem;
    transform: rotate(0deg);
  }

  .poster.reveal,
  .poster.reveal.visible {
    transform: none;
  }

  .tally {
    gap: 1.6rem;
  }

  .code-panel pre {
    padding: 1.4rem;
  }

  .code-tabs button {
    padding: 0.9rem 0.9rem;
    font-size: 0.7rem;
  }

  footer {
    grid-template-columns: 1fr;
    justify-items: center;
    text-align: center;
  }

  footer p:last-child {
    justify-self: center;
  }
}

toolArgs.file_text:
:root {
  --night: #17100a;
  --ink: #2b1a0e;
  --leather: #5a3320;
  --rust: #b5461f;
  --gold: #e0a32e;
  --ember: #f2a03d;
  --sand: #e6d3ae;
  --parchment: #f4e8ce;
  --cactus: #6b8558;
  --muted: #8a7458;

  --display: "Rye", "Bitter", Georgia, serif;
  --slab: "Smokum", "Rye", Georgia, serif;
  --type: "Special Elite", "Courier New", monospace;
  --body: "Bitter", Georgia, "Times New Roman", serif;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  color: var(--ink);
  background: var(--parchment);
  font-family: var(--body);
  font-size: 16px;
  line-height: 1.6;
  overflow-x: hidden;
}

::selection {
  color: var(--parchment);
  background: var(--rust);
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  display: block;
  max-width: 100%;
}

button {
  font: inherit;
}

.skip-link {
  position: fixed;
  z-index: 100;
  top: 1rem;
  left: 1rem;
  padding: 0.7rem 1rem;
  color: var(--parchment);
  background: var(--rust);
  font-family: var(--type);
  transform: translateY(-250%);
}

.skip-link:focus {
  transform: translateY(0);
}

/* Aged paper grain over the whole page */
.grain {
  position: fixed;
  z-index: 30;
  inset: 0;
  pointer-events: none;
  opacity: 0.09;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

/* ---------- Header ---------- */

.site-header {
  position: absolute;
  z-index: 10;
  top: 0;
  left: 0;
  display: grid;
  width: 100%;
  grid-template-columns: 1fr auto 1fr;
  gap: 1.5rem;
  align-items: center;
  padding: 1.1rem 3.5vw;
  color: var(--parchment);
  border-bottom: 1px solid rgba(240, 220, 180, 0.22);
}

.brand {
  display: inline-flex;
  gap: 0.75rem;
  align-items: center;
  width: max-content;
}

.brand-hat {
  color: var(--gold);
  filter: drop-shadow(0 2px 0 rgba(0, 0, 0, 0.35));
}

.brand-text {
  display: grid;
  line-height: 1.1;
}

.brand-text strong {
  font-family: var(--display);
  font-size: 1.05rem;
  font-weight: 400;
  letter-spacing: 0.06em;
}

.brand-text em {
  color: var(--gold);
  font-family: var(--type);
  font-size: 0.6rem;
  font-style: normal;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

nav {
  display: flex;
  gap: 2.2rem;
  font-family: var(--type);
  font-size: 0.76rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

nav a {
  padding-bottom: 0.2rem;
  border-bottom: 1px solid transparent;
  transition: color 160ms ease, border-color 160ms ease;
}

nav a:hover {
  color: var(--gold);
  border-bottom-color: var(--gold);
}

.site-header > .button {
  justify-self: end;
}

/* ---------- Buttons ---------- */

.button {
  display: inline-flex;
  gap: 1.1rem;
  align-items: center;
  justify-content: space-between;
  padding: 0.85rem 1.4rem;
  border: 2px solid currentColor;
  border-radius: 2px;
  font-family: var(--type);
  font-size: 0.78rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: transform 180ms ease, color 180ms ease, background 180ms ease,
    box-shadow 180ms ease;
}

.button:hover {
  transform: translateY(-3px);
}

.button-ghost {
  border-color: rgba(240, 220, 180, 0.5);
}

.button-ghost:hover {
  color: var(--ink);
  background: var(--sand);
  border-color: var(--sand);
}

.button-primary {
  color: var(--ink);
  background: var(--gold);
  border-color: var(--ink);
  box-shadow: 4px 4px 0 var(--ink);
}

.button-primary:hover {
  background: var(--ember);
  box-shadow: 7px 7px 0 var(--ink);
}

.button-dark {
  color: var(--parchment);
  background: var(--ink);
  border-color: var(--ink);
  box-shadow: 4px 4px 0 rgba(43, 26, 14, 0.28);
}

.button-dark:hover {
  background: var(--leather);
  box-shadow: 7px 7px 0 rgba(43, 26, 14, 0.28);
}

.text-link {
  padding-bottom: 0.3rem;
  border-bottom: 1px solid currentColor;
  font-family: var(--type);
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transition: color 160ms ease;
}

.text-link:hover {
  color: var(--gold);
}

/* ---------- Hero ---------- */

.hero {
  position: relative;
  display: grid;
  min-height: 100vh;
  padding: 10rem 6vw 7rem;
  grid-template-columns: minmax(0, 1.05fr) minmax(360px, 0.95fr);
  gap: 5vw;
  align-items: center;
  color: var(--parchment);
  background: var(--night);
  overflow: hidden;
}

.hero-scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(105deg, rgba(15, 9, 5, 0.9) 8%, rgba(15, 9, 5, 0.55) 46%, rgba(15, 9, 5, 0.25) 72%),
    linear-gradient(to top, rgba(15, 9, 5, 0.85), transparent 45%);
}

.hero-copy,
.telegram {
  position: relative;
  z-index: 2;
}

.eyebrow {
  display: inline-flex;
  gap: 0.7rem;
  align-items: center;
  margin: 0 0 1.8rem;
  padding: 0.45rem 0.95rem;
  color: var(--gold);
  border: 1px solid rgba(224, 163, 46, 0.55);
  border-radius: 2px;
  background: rgba(20, 12, 6, 0.5);
  font-family: var(--type);
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.eyebrow img {
  color: var(--gold);
}

h1 {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(3.2rem, 8vw, 7.2rem);
  font-weight: 400;
  line-height: 0.98;
  text-shadow: 5px 5px 0 rgba(0, 0, 0, 0.45);
}

h1 span {
  display: block;
}

h1 .line-2 {
  padding-left: 0.12em;
  color: var(--gold);
}

h1 .line-3 {
  padding-left: 0.24em;
  color: var(--ember);
}

.hero-intro {
  max-width: 34rem;
  margin: 2.2rem 0 2.4rem;
  color: #ded0b6;
  font-size: clamp(1rem, 1.4vw, 1.2rem);
  line-height: 1.75;
}

.hero-actions {
  display: flex;
  gap: 2rem;
  align-items: center;
  flex-wrap: wrap;
}

.hero-index {
  position: absolute;
  right: 1.6rem;
  bottom: 2.5rem;
  color: rgba(224, 163, 46, 0.65);
  font-family: var(--type);
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  writing-mode: vertical-rl;
}

/* ---------- Telegram card ---------- */

.telegram {
  background: var(--parchment);
  border: 2px solid var(--ink);
  border-radius: 3px;
  box-shadow: 14px 14px 0 rgba(0, 0, 0, 0.35);
  transform: rotate(-1.4deg);
}

.telegram-head {
  display: flex;
  justify-content: space-between;
  padding: 0.7rem 1.1rem;
  color: var(--parchment);
  background: var(--ink);
  font-family: var(--type);
  font-size: 0.66rem;
  letter-spacing: 0.14em;
}

.telegram-body {
  min-height: 400px;
  padding: 1.8rem;
  color: var(--leather);
  font-family: var(--type);
  font-size: clamp(0.74rem, 1vw, 0.92rem);
  line-height: 1.9;
}

.telegram-body p {
  margin: 0;
}

.telegram-meta {
  margin-bottom: 1rem !important;
  padding-bottom: 0.6rem;
  color: var(--rust);
  border-bottom: 1px dashed rgba(90, 51, 32, 0.4);
  font-size: 0.7rem;
  letter-spacing: 0.08em;
}

.telegram-body .telegram-meta:last-child {
  margin: 1rem 0 0 !important;
  padding: 0.6rem 0 0;
  border-top: 1px dashed rgba(90, 51, 32, 0.4);
  border-bottom: 0;
}

.telegram-body .prompt {
  color: var(--rust);
  font-weight: 700;
}

.tree {
  margin: 0.9rem 0;
}

.tree b {
  color: var(--ink);
}

.tree i {
  color: var(--muted);
  font-size: 0.8em;
}

.cursor {
  color: var(--rust);
  animation: blink 1.05s step-end infinite;
}

@keyframes blink {
  50% { opacity: 0; }
}

/* ---------- Rope divider ---------- */

.rope-divider {
  height: 14px;
  background: url("assets/rope.svg") repeat-x center / auto 14px;
  border-top: 2px solid var(--ink);
  border-bottom: 2px solid var(--ink);
  background-color: var(--sand);
}

/* ---------- Shared section furniture ---------- */

.section {
  padding: 7rem 6vw;
}

.section-label {
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  margin-bottom: 3.5rem;
  font-family: var(--type);
  font-size: 0.74rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.section-label span {
  color: var(--rust);
}

.section-label p {
  margin: 0;
}

.section-label.light {
  color: var(--sand);
}

.section-label.light span {
  color: var(--gold);
}

.overline {
  display: block;
  margin-bottom: 1.3rem;
  color: var(--rust);
  font-family: var(--type);
  font-size: 0.74rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

h2 {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(2.6rem, 5.4vw, 5rem);
  font-weight: 400;
  line-height: 1.05;
}

h2 em {
  display: inline-block;
  color: var(--rust);
  font-family: var(--slab);
  font-size: 1.22em;
  font-style: normal;
  line-height: 0.9;
}

/* ---------- Wanted poster ---------- */

.poster-section {
  background:
    radial-gradient(circle at 15% 12%, rgba(224, 163, 46, 0.16), transparent 45%),
    radial-gradient(circle at 85% 80%, rgba(181, 70, 31, 0.12), transparent 50%),
    var(--parchment);
}

.poster-grid {
  display: grid;
  grid-template-columns: minmax(300px, 0.8fr) 1.2fr;
  gap: 6vw;
  align-items: center;
}

.poster {
  padding: 2.2rem 1.8rem;
  text-align: center;
  color: var(--leather);
  background:
    radial-gradient(circle at 50% 0%, #fbf2dd, #e8d5ab 78%);
  border: 3px double var(--leather);
  box-shadow: 0 0 0 1px var(--sand), 10px 12px 0 rgba(43, 26, 14, 0.2);
  transform: rotate(-2deg);
  transition: transform 300ms ease;
}

.poster:hover {
  transform: rotate(0deg) scale(1.02);
}

.poster-top,
.poster-foot {
  margin: 0;
  color: var(--rust);
  font-family: var(--type);
  font-size: 0.66rem;
  letter-spacing: 0.14em;
}

.poster-title {
  margin: 0.5rem 0 0;
  color: var(--ink);
  font-family: var(--slab);
  font-size: clamp(3.6rem, 7vw, 5.4rem);
  line-height: 0.9;
}

.poster-sub {
  margin: 0 0 1.2rem;
  font-family: var(--type);
  font-size: 0.82rem;
  letter-spacing: 0.06em;
}

.poster-portrait {
  margin: 0 auto 1.2rem;
  padding: 1rem;
  color: var(--leather);
  border: 2px solid rgba(90, 51, 32, 0.45);
  background: rgba(255, 255, 255, 0.28);
}

.poster-name {
  margin: 0 0 1.3rem;
  color: var(--ink);
  font-family: var(--display);
  font-size: 1.25rem;
}

.poster-facts {
  margin: 0 0 1.5rem;
  padding-top: 1rem;
  border-top: 1px solid rgba(90, 51, 32, 0.35);
  font-family: var(--type);
  font-size: 0.8rem;
  text-align: left;
}

.poster-facts > div {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.35rem 0;
  border-bottom: 1px dotted rgba(90, 51, 32, 0.3);
}

.poster-facts dt {
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.72rem;
}

.poster-facts dd {
  margin: 0;
  color: var(--ink);
}

.poster-foot {
  padding-top: 0.6rem;
}

.kicker {
  margin: 0 0 1.6rem;
  font-family: var(--display);
  font-size: clamp(2.2rem, 4.4vw, 3.9rem);
  line-height: 1.12;
}

.kicker em {
  color: var(--rust);
  font-family: var(--slab);
  font-size: 1.25em;
  font-style: normal;
}

.poster-copy > p:not(.kicker) {
  max-width: 34rem;
  margin: 0;
  color: #5f4a33;
  font-size: 1.06rem;
  line-height: 1.85;
}

.tally {
  display: flex;
  gap: 2.6rem;
  margin: 2.6rem 0 0;
  padding: 1.4rem 0 0;
  border-top: 2px solid var(--ink);
  list-style: none;
  flex-wrap: wrap;
}

.tally strong {
  display: block;
  color: var(--rust);
  font-family: var(--display);
  font-size: 2.4rem;
  line-height: 1;
}

.tally span {
  font-family: var(--type);
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- Supplies ---------- */

.supplies {
  background: var(--sand);
  border-top: 2px solid var(--ink);
  border-bottom: 2px solid var(--ink);
}

.section-heading,
.workflow-header {
  display: flex;
  gap: 3rem;
  margin-bottom: 4rem;
  align-items: flex-end;
  justify-content: space-between;
}

.section-heading > p,
.workflow-header > p,
.start-copy > p {
  max-width: 27rem;
  margin: 0;
  color: #5f4a33;
  font-size: 1.02rem;
  line-height: 1.8;
}

.supply-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.supply-card {
  display: flex;
  min-height: 400px;
  padding: 2rem;
  flex-direction: column;
  color: var(--leather);
  background: var(--parchment);
  border: 2px solid var(--ink);
  border-radius: 3px;
  box-shadow: 8px 8px 0 rgba(43, 26, 14, 0.22);
  transition: transform 220ms ease, box-shadow 220ms ease, background 220ms ease;
}

.supply-card:hover {
  background: #fbf3e0;
  box-shadow: 12px 12px 0 rgba(43, 26, 14, 0.3);
  transform: translateY(-6px);
}

.card-number {
  font-family: var(--type);
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  color: var(--rust);
}

.supply-card img {
  margin: auto 0 1.5rem;
  color: var(--leather);
}

.supply-card:nth-child(2) img {
  color: var(--rust);
}

.supply-card:nth-child(3) img {
  color: var(--cactus);
}

.supply-card h3 {
  margin: 0 0 0.7rem;
  color: var(--ink);
  font-family: var(--display);
  font-size: 1.55rem;
  font-weight: 400;
}

.supply-card p {
  min-height: 5.5rem;
  margin: 0 0 1.4rem;
  color: #67513a;
  line-height: 1.7;
}

.supply-card code,
.workflow-list code {
  width: max-content;
  padding: 0.35rem 0.6rem;
  color: var(--parchment);
  background: var(--leather);
  border-radius: 2px;
  font-family: var(--type);
  font-size: 0.72rem;
}

/* ---------- Workflows ---------- */

.workflows {
  position: relative;
  color: var(--sand);
  background:
    linear-gradient(rgba(23, 16, 10, 0.94), rgba(23, 16, 10, 0.94)),
    repeating-linear-gradient(
      92deg,
      #2f1d10 0 7px,
      #3a2414 7px 9px,
      #241608 9px 22px
    );
  overflow: hidden;
}

.workflow-cactus {
  position: absolute;
  right: 3vw;
  bottom: 3rem;
  color: rgba(107, 133, 88, 0.28);
  pointer-events: none;
}

.workflow-header h2 em {
  color: var(--gold);
}

.workflow-header > p {
  color: #bda98a;
}

.workflow-list {
  position: relative;
  z-index: 2;
  border-top: 1px solid rgba(224, 163, 46, 0.28);
}

.workflow-list a {
  display: grid;
  padding: 1.5rem 0.6rem;
  grid-template-columns: 0.35fr 1.3fr 2fr 0.85fr auto;
  gap: 1.2rem;
  align-items: center;
  border-bottom: 1px solid rgba(224, 163, 46, 0.28);
  transition: padding 200ms ease, color 200ms ease, background 200ms ease;
}

.workflow-list a:hover {
  padding-right: 1.2rem;
  padding-left: 1.2rem;
  color: var(--ink);
  background: var(--gold);
}

.workflow-id {
  color: var(--gold);
  font-family: var(--type);
  font-size: 0.74rem;
}

.workflow-list strong {
  font-family: var(--display);
  font-size: 1.15rem;
  font-weight: 400;
}

.workflow-desc {
  color: #bda98a;
  font-size: 0.95rem;
}

.workflow-list b {
  font-size: 1.1rem;
}

.workflow-list a:hover .workflow-id,
.workflow-list a:hover .workflow-desc {
  color: var(--ink);
}

.workflow-list a:hover code {
  color: var(--gold);
  background: var(--ink);
}

/* ---------- Start ---------- */

.start {
  background:
    radial-gradient(circle at 80% 15%, rgba(224, 163, 46, 0.22), transparent 55%),
    var(--parchment);
  border-bottom: 2px solid var(--ink);
}

.start-grid {
  display: grid;
  grid-template-columns: 1fr 1.15fr;
  gap: 6vw;
  align-items: center;
}

.start-copy {
  position: relative;
}

.start-copy h2 em {
  color: var(--rust);
}

.start-copy > p {
  margin: 1.8rem 0 2.2rem;
}

.start-boot {
  position: absolute;
  right: 1rem;
  bottom: -2rem;
  color: rgba(90, 51, 32, 0.22);
  pointer-events: none;
  transform: rotate(-12deg);
}

.code-panel {
  color: var(--sand);
  background: var(--ink);
  border: 2px solid var(--ink);
  border-radius: 3px;
  box-shadow: 12px 12px 0 rgba(43, 26, 14, 0.25);
}

.code-tabs {
  display: flex;
  border-bottom: 1px solid rgba(224, 163, 46, 0.35);
}

.code-tabs button {
  padding: 1rem 1.4rem;
  border: 0;
  color: #a08f74;
  background: transparent;
  cursor: pointer;
  font-family: var(--type);
  font-size: 0.76rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  transition: color 160ms ease, box-shadow 160ms ease;
}

.code-tabs button.active {
  color: var(--gold);
  box-shadow: inset 0 -3px var(--gold);
}

.code-tabs button:hover {
  color: var(--ember);
}

.code-tabs .copy-button {
  margin-left: auto;
  color: var(--sand);
}

.code-panel pre {
  min-height: 235px;
  margin: 0;
  padding: 2.2rem;
  overflow: auto;
  font-family: var(--type);
  font-size: clamp(0.76rem, 1.05vw, 0.94rem);
  line-height: 2.1;
}

.code-panel .comment {
  color: #97835f;
}

/* ---------- CTA ---------- */

.cta {
  position: relative;
  padding: 9rem 6vw 7rem;
  color: var(--parchment);
  background: var(--night);
  overflow: hidden;
  text-align: center;
}

.cta::after {
  position: absolute;
  left: 50%;
  bottom: -18rem;
  width: 36rem;
  height: 36rem;
  margin-left: -18rem;
  content: "";
  border-radius: 50%;
  background: radial-gradient(circle, rgba(224, 163, 46, 0.35), transparent 68%);
}

.cta-track {
  position: absolute;
  top: 2.2rem;
  left: 0;
  display: flex;
  width: max-content;
  color: rgba(224, 163, 46, 0.22);
  font-family: var(--display);
  font-size: 1.5rem;
  white-space: nowrap;
  animation: marquee 28s linear infinite;
}

@keyframes marquee {
  to { transform: translateX(-50%); }
}

.cta-inner {
  position: relative;
  z-index: 2;
  display: grid;
  justify-items: center;
}

.cta-inner img {
  color: var(--gold);
  margin-bottom: 1.5rem;
}

.cta-inner > p {
  margin: 0 0 1.6rem;
  color: var(--gold);
  font-family: var(--type);
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.cta h2 {
  margin-bottom: 3rem;
  text-shadow: 4px 4px 0 rgba(0, 0, 0, 0.4);
}

.cta h2 em {
  color: var(--gold);
}

/* ---------- Footer ---------- */

footer {
  display: grid;
  padding: 2rem 3.5vw;
  grid-template-columns: 1fr auto 1fr;
  gap: 1.5rem;
  align-items: center;
  color: #a08f74;
  background: var(--ink);
  border-top: 2px solid var(--gold);
  font-family: var(--type);
  font-size: 0.72rem;
  letter-spacing: 0.06em;
}

footer .brand-text strong {
  color: var(--sand);
}

footer p {
  margin: 0;
}

footer p:last-child {
  justify-self: end;
}

/* ---------- Reveal animation ---------- */

.reveal {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 700ms ease, transform 700ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

.poster.reveal {
  transform: translateY(26px) rotate(-2deg);
}

.poster.reveal.visible {
  transform: translateY(0) rotate(-2deg);
}

.telegram.reveal {
  transform: translateY(26px) rotate(-1.4deg);
}

.telegram.reveal.visible {
  transform: translateY(0) rotate(-1.4deg);
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .reveal,
  .poster.reveal,
  .telegram.reveal { opacity: 1; transform: none; transition: none; }
  .poster.reveal.visible { transform: rotate(-2deg); }
  .telegram.reveal.visible { transform: rotate(-1.4deg); }
  .cta-track, .cursor { animation: none; }
  .button, .supply-card, .poster { transition: none; }
}

/* ---------- Responsive ---------- */

@media (max-width: 1000px) {
  .site-header {
    grid-template-columns: 1fr auto;
  }

  .site-header nav {
    display: none;
  }

  .hero {
    min-height: auto;
    padding-top: 8.5rem;
    grid-template-columns: 1fr;
    gap: 3.5rem;
  }

  .hero-shade {
    background: linear-gradient(to top, rgba(15, 9, 5, 0.94) 30%, rgba(15, 9, 5, 0.6));
  }

  .telegram {
    max-width: 620px;
  }

  .hero-index {
    display: none;
  }

  .poster-grid,
  .start-grid {
    grid-template-columns: 1fr;
    gap: 3.5rem;
  }

  .poster {
    max-width: 420px;
  }

  .supply-grid {
    grid-template-columns: 1fr;
  }

  .supply-card {
    min-height: 0;
  }

  .supply-card img {
    margin-top: 2rem;
  }

  .supply-card p {
    min-height: 0;
  }

  .section-heading,
  .workflow-header {
    gap: 1.8rem;
    align-items: flex-start;
    flex-direction: column;
  }

  .workflow-list a {
    grid-template-columns: 0.4fr 1fr auto;
  }

  .workflow-desc,
  .workflow-list code {
    display: none;
  }

  .workflow-cactus {
    width: 120px;
    height: 120px;
    opacity: 0.5;
  }

  .start-boot {
    display: none;
  }
}

@media (max-width: 620px) {
  .site-header {
    padding: 0.9rem 1.1rem;
  }

  .site-header > .button {
    display: none;
  }

  .hero,
  .section,
  .cta {
    padding-right: 1.2rem;
    padding-left: 1.2rem;
  }

  .hero {
    padding-top: 7.5rem;
    padding-bottom: 4rem;
  }

  .section {
    padding-top: 4.5rem;
    padding-bottom: 4.5rem;
  }

  .cta {
    padding-top: 6.5rem;
  }

  h1 {
    font-size: clamp(2.6rem, 13vw, 4rem);
  }

  h2 {
    font-size: clamp(2rem, 9.5vw, 3rem);
  }

  .hero-actions {
    align-items: flex-start;
    flex-direction: column;
    gap: 1.4rem;
  }

  .telegram-body {
    min-height: 0;
    padding: 1.2rem;
  }

  .poster {
    padding: 1.6rem 1.1rem;
    transform: rotate(0deg);
  }

  .poster.reveal,
  .poster.reveal.visible {
    transform: none;
  }

  .tally {
    gap: 1.6rem;
  }

  .code-panel pre {
    padding: 1.4rem;
  }

  .code-tabs button {
    padding: 0.9rem 0.9rem;
    font-size: 0.7rem;
  }

  footer {
    grid-template-columns: 1fr;
    justify-items: center;
    text-align: center;
  }

  footer p:last-child {
    justify-self: center;
  }
}

