args.file_text:
const { chromium } = require("playwright");

(async () => {
  const browser = await chromium.launch();
  const errors = [];

  const desktop = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  desktop.on("console", (m) => m.type() === "error" && errors.push("console: " + m.text()));
  desktop.on("pageerror", (e) => errors.push("pageerror: " + e.message));
  desktop.on("requestfailed", (r) => errors.push("failed: " + r.url()));

  await desktop.goto("http://127.0.0.1:4173/", { waitUntil: "networkidle" });
  await desktop.waitForTimeout(1200);

  // Report computed font families so we know Google Fonts actually applied.
  const fonts = await desktop.evaluate(() => {
    const seen = {};
    for (const sel of ["h1", ".hero-intro", ".eyebrow", ".poster-title"]) {
      const el = document.querySelector(sel);
      if (el) seen[sel] = getComputedStyle(el).fontFamily;
    }
    seen.loadedFonts = [...new Set([...document.fonts].map((f) => f.family))].join(", ");
    return seen;
  });

  // Confirm masked icons have real painted size.
  const icons = await desktop.evaluate(() =>
    [...document.querySelectorAll(".ico")].map((el) => {
      const r = el.getBoundingClientRect();
      const s = getComputedStyle(el);
      return `${el.className.split(" ")[1]} ${Math.round(r.width)}x${Math.round(r.height)} mask=${(s.maskImage || s.webkitMaskImage).slice(0, 24)}`;
    }),
  );

  await desktop.screenshot({ path: "shot-hero.png" });
  await desktop.screenshot({ path: "shot-full.png", fullPage: true });

  // Exercise the tab + copy interaction.
  await desktop.click('[data-command="docker"]');
  await desktop.waitForTimeout(300);
  const dockerText = await desktop.textContent("#setup-command");

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await mobile.goto("http://127.0.0.1:4173/", { waitUntil: "networkidle" });
  await mobile.waitForTimeout(1200);
  await mobile.screenshot({ path: "shot-mobile.png", fullPage: true });
  const overflow = await mobile.evaluate(
    () => document.documentElement.scrollWidth - document.documentElement.clientWidth,
  );

  console.log("FONTS:", JSON.stringify(fonts, null, 2));
  console.log("ICONS:\n" + icons.join("\n"));
  console.log("DOCKER TAB:", JSON.stringify(dockerText));
  console.log("MOBILE H-OVERFLOW PX:", overflow);
  console.log("ERRORS:", errors.length ? errors.join("\n") : "none");

  await browser.close();
})();

