const { chromium } = require("playwright");

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await page.goto("http://127.0.0.1:4173/", { waitUntil: "networkidle" });
  await page.waitForTimeout(800);

  const offenders = await page.evaluate(() => {
    const limit = document.documentElement.clientWidth;
    return [...document.querySelectorAll("*")]
      .map((el) => {
        const r = el.getBoundingClientRect();
        return { tag: el.tagName.toLowerCase(), cls: el.className.toString().slice(0, 45), right: Math.round(r.right), left: Math.round(r.left) };
      })
      .filter((x) => x.right > limit + 1)
      .slice(0, 20);
  });

  console.log("VIEWPORT 390 — overflowing elements:");
  console.log(offenders.map((o) => `${o.tag}.${o.cls} left=${o.left} right=${o.right}`).join("\n") || "none");
  await browser.close();
})();

