.reveal {
  transition: opacity 700ms ease, transform 700ms cubic-bezier(0.2, 0.7, 0.2, 1);
}

.js .reveal {
  opacity: 0;
  transform: translateY(26px);
}

.js .reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

.js .poster.reveal {
  transform: translateY(26px) rotate(-2deg);
}

.js .poster.reveal.visible {
  transform: translateY(0) rotate(-2deg);
}

.js .telegram.reveal {
  transform: translateY(26px) rotate(-1.4deg);
}

.js .telegram.reveal.visible {
  transform: translateY(0) rotate(-1.4deg);
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .js .reveal,
  .js .poster.reveal,
  .js .telegram.reveal { opacity: 1; transform: none; transition: none; }
  .js .poster.reveal { transform: rotate(-2deg); }
  .js .telegram.reveal { transform: rotate(-1.4deg); }
  .cta-track, .cursor { animation: none; }
  .button, .supply-card, .poster { transition: none; }
}

