const { chromium } = require("playwright");

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto("http://127.0.0.1:4173/", { waitUntil: "networkidle" });
  await page.waitForTimeout(1000);
  await page.screenshot({ path: "sec-hero.png" });

  const sections = [
    ["#about", "sec-poster.png"],
    ["#supplies", "sec-supplies.png"],
    ["#workflows", "sec-workflows.png"],
    ["#start", "sec-start.png"],
    [".cta", "sec-cta.png"],
  ];

  for (const [selector, file] of sections) {
    await page.evaluate((s) => {
      document.querySelector(s).scrollIntoView({ behavior: "instant", block: "start" });
    }, selector);
    await page.waitForTimeout(1100);
    await page.screenshot({ path: file });
  }

  console.log("captured", sections.length + 1, "views");
  await browser.close();
})();

