args.file_text:
const { chromium } = require("playwright");

(async () => {
  const browser = await chromium.launch();

  // Content must remain visible when scripting is unavailable.
  const ctx = await browser.newContext({ javaScriptEnabled: false, viewport: { width: 1440, height: 900 } });
  const nojs = await ctx.newPage();
  await nojs.goto("http://127.0.0.1:4173/", { waitUntil: "load" });
  await nojs.waitForTimeout(600);
  const hiddenCount = await nojs.evaluate(
    () => [...document.querySelectorAll(".reveal")].filter((el) => getComputedStyle(el).opacity === "0").length,
  );
  await nojs.screenshot({ path: "shot-nojs.png", fullPage: true });
  console.log("NO-JS hidden .reveal elements:", hiddenCount);

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await mobile.goto("http://127.0.0.1:4173/", { waitUntil: "networkidle" });
  await mobile.waitForTimeout(900);
  await mobile.screenshot({ path: "shot-m-hero.png" });
  for (const sel of ["#about", "#supplies", "#workflows", "#start"]) {
    await mobile.evaluate((s) => document.querySelector(s).scrollIntoView(), sel);
    await mobile.waitForTimeout(900);
  }
  await mobile.evaluate(() => window.scrollTo(0, 0));
  await mobile.waitForTimeout(400);
  await mobile.screenshot({ path: "shot-m-full.png", fullPage: true });
  console.log("mobile captured");

  await browser.close();
})();

